enhanced_schema:
{
  "tables": [
    {
      "table_name": "ic_products",
      "table_description": "Table to store specifications and details of integrated circuit products.",
      "columns": [
        {
          "name": "order_number",
          "type": "VARCHAR",
          "description": "Unique order number for the IC product"
        },
        {
          "name": "package_type",
          "type": "VARCHAR",
          "description": "Type of packaging used for the IC"
        },
        {
          "name": "temperature_rating",
          "type": "VARCHAR",
          "description": "Temperature classification of the IC (e.g., Standard, Wide)"
        },
        {
          "name": "tpm_library_revision",
          "type": "FLOAT",
          "description": "Revision number of the TPM 2.0 library used"
        },
        {
          "name": "fw_us_version",
          "type": "VARCHAR",
          "description": "Version of the firmware for the US region"
        },
        {
          "name": "description",
          "type": "TEXT",
          "description": "Detailed description of the IC product"
        },
        {
          "name": "release_date",
          "type": "DATE",
          "description": "Date when the product version was released"
        },
        {
          "name": "end_of_life_date",
          "type": "DATE",
          "description": "Date when the product is expected to be discontinued"
        },
        {
          "name": "status",
          "type": "VARCHAR",
          "description": "Current status of the product (e.g., Active, Discontinued)"
        },
        {
          "name": "created_by",
          "type": "VARCHAR",
          "description": "User who created the product entry"
        },
        {
          "name": "updated_by",
          "type": "VARCHAR",
          "description": "User who last updated the product entry"
        },
        {
          "name": "last_updated",
          "type": "TIMESTAMP",
          "description": "Timestamp of the last update"
        }
      ],
      "primary_key": [
        "order_number"
      ]
    },
    {
      "table_name": "product_versions",
      "table_description": "Table to store different versions of product specifications.",
      "columns": [
        {
          "name": "version_id",
          "type": "INT",
          "description": "Unique identifier for the product version"
        },
        {
          "name": "order_number",
          "type": "VARCHAR",
          "description": "Foreign key reference to IC product"
        },
        {
          "name": "version",
          "type": "VARCHAR",
          "description": "Version identifier"
        },
        {
          "name": "release_notes",
          "type": "TEXT",
          "description": "Notes on what is included in this version"
        },
        {
          "name": "release_date",
          "type": "DATE",
          "description": "Date of version release"
        }
      ],
      "primary_key": [
        "version_id"
      ],
      "foreign_keys": [
        {
          "column": "order_number",
          "references": {
            "table": "ic_products",
            "column": "order_number"
          }
        }
      ]
    },
    {
      "table_name": "product_attributes",
      "table_description": "Dynamic attributes for IC products.",
      "columns": [
        {
          "name": "attribute_id",
          "type": "INT",
          "description": "Unique identifier for product attribute"
        },
        {
          "name": "order_number",
          "type": "VARCHAR",
          "description": "Foreign key reference to IC product"
        },
        {
          "name": "attribute_name",
          "type": "VARCHAR",
          "description": "Name of the attribute"
        },
        {
          "name": "attribute_value",
          "type": "VARCHAR",
          "description": "Value of the attribute"
        }
      ],
      "primary_key": [
        "attribute_id"
      ],
      "foreign_keys": [
        {
          "column": "order_number",
          "references": {
            "table": "ic_products",
            "column": "order_number"
          }
        }
      ]
    },
    {
      "table_name": "collaborations",
      "table_description": "Tracks collaborations and updates on product specifications.",
      "columns": [
        {
          "name": "collaboration_id",
          "type": "INT",
          "description": "Unique identifier for collaboration entry"
        },
        {
          "name": "order_number",
          "type": "VARCHAR",
          "description": "Foreign key reference to IC product"
        },
        {
          "name": "user_id",
          "type": "VARCHAR",
          "description": "User involved in the collaboration"
        },
        {
          "name": "update_type",
          "type": "VARCHAR",
          "description": "Type of update made"
        },
        {
          "name": "comments",
          "type": "TEXT",
          "description": "Comments or notes about the update"
        },
        {
          "name": "timestamp",
          "type": "TIMESTAMP",
          "description": "When the update was made"
        }
      ],
      "primary_key": [
        "collaboration_id"
      ],
      "foreign_keys": [
        {
          "column": "order_number",
          "references": {
            "table": "ic_products",
            "column": "order_number"
          }
        }
      ]
    }
  ]
}
